from _lib import File
F=File('pre2020_ktm250f','o-k25','KTM 250 SX-F 2011-2019 by generation (2011-2012, 2013-2015, 2016-2018, 2019): what changed, dyno and weight, tester settings, maps, gearing, known problems and fixes (knowledge push 2026-11)','KTM',['250 SX-F'],list(range(2011,2020)))
R=F.R; M='magazine'; C=['250 SX-F']

s=F.src(M,"Motocross Action - 2011 KTM 250SXF test","https://motocrossactionmag.com/2011-ktm-250sxf-motocross-test-the-bike-that-won-the-250-world-championship-with-linkage-and-fuel-injection","2010")
G=[2011,2012]
R('identity','2011 changes',C,[2011],"2011 250 SX-F changes: fuel injection through a 42 mm Keihin throttle body, a linkage shock in place of PDS with a revised swingarm, shorter valve timing with reshaped intake ports, a tapered head pipe with a shorter muffler and new bodywork. Injection and linkage added about 5 lb.",{'throttle_body_mm':42,'rear':'linkage'},'OEM',s)
R('power_feel','2011-2012 dyno and weight',C,G,"On a magazine dyno the 250 SX-F made 36.41 hp at 10,800 rpm and 19.96 lb-ft in 2011, and 35.52 hp at 10,800 rpm and 19.43 lb-ft in 2012. With the electric starter added for 2012 it weighed 231 lb, the heaviest 250 four-stroke of its year. More bottom and middle than the carburetted 2010 but slow to rev and soft off idle.",{'peak_hp_2011':36.41,'peak_hp_2012':35.52,'peak_rpm':10800,'weight_lb_2012':231},'MEASURED',s,'high')
R('setups','2011 tester settings',C,[2011],"A magazine test crew's 2011 250 SX-F setup: fork 0.48 kg/mm springs (stock 0.46), 360 cc oil (stock 380; drop in 5 cc steps), compression 13 clicks out (stock 12), rebound 12 out, legs 5 mm up. Shock 5.7 kg/mm spring (stock 5.4), 102 mm sag, high-speed compression 2-1/4 turns out, low-speed 18 clicks out (stock 15), rebound 15 out. The stock springs are too soft for riders over about 150 lb, and the fork needs about an hour to break in. Rear sprocket 49 in place of 48.",{'fork':'0.48 kg/mm (stock 0.46), 360 cc, comp 13 out, reb 12 out, 5 mm up','shock':'5.7 kg/mm (stock 5.4), sag 102 mm, HSC 2-1/4 turns, LSC 18 out, reb 15 out','gearing':'13/49 (stock 13/48)'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2012 KTM 250SXF test","https://motocrossactionmag.com/mxas-2012-ktm-250sxf-motocross-test-did-ktm-grab-for-too-much-of-the-brass-ring","2011")
R('identity','2012 changes',C,[2012],"2012 250 SX-F changes: an electric starter shared with the 350 (about 5 lb), a softer base map for hot conditions plus two extra maps reached with KTM's accessory switch, a rubber-covered throttle position sensor, revalved suspension with new seals, a reshaped air boot, a redesigned rear master-cylinder piston and a reinforced rear fender. Stock rear sprocket became 49.",{'starter':'electric'},'OEM',s2)
R('setups','2012 tester settings',C,[2012],"A magazine test crew's 2012 250 SX-F setup: fork 0.46 kg/mm springs, 365 cc oil (stock 380), compression 9 clicks out (stock 11), rebound 10 out (stock 12), legs 5 mm up. Shock 5.4 kg/mm spring (stock 5.1; riders over 160 lb need it), 102 mm sag, high-speed compression 2-1/4 turns out (stock 2), low-speed 14 clicks out (stock 15), rebound 14 out. Rear sprocket 50 in place of 49. Loading the 2011 aggressive ignition map made it rev quicker.",{'fork':'365 cc (stock 380), comp 9 out, reb 10 out, 5 mm up','shock':'5.4 kg/mm (stock 5.1), sag 102 mm, HSC 2-1/4 turns, LSC 14 out, reb 14 out','gearing':'13/50 (stock 13/49)'},'TUNER',s2)
R('known_issues','2011-2012 weak points',C,G,"Tester findings on the 2011-2012 250 SX-F: undersprung at both ends for riders over 150-160 lb, soft rims on 2011 bikes with spokes that need constant attention (improved for 2012), low bar mounts for tall riders (5 mm taller mounts or a taller bend), coolant pushed out of the overflow at idle, the stock exhaust needing the shock out to remove, and the plastic shock preload ring.",{},'TUNER',s2)

s=F.src(M,"Motocross Action - 2013 KTM 250SXF test","https://motocrossactionmag.com/mxas-2013-ktm-250sxf-motocross-test-the-most-powerful-production-250-four-stroke-ever","2012")
G=[2013,2014,2015]
R('identity','2013 redesign',C,G,"The 2013 250 SX-F got a new engine: bore up 2 mm and stroke down 2.5 mm, intake valves enlarged from 30.9 to 32.5 mm, die-cast cases, a plain-bearing rod, a 44 mm throttle body (was 42), a six-speed gearbox with a revised second gear, an exhaust that pulls out from the front, plus a new frame, swingarm and clamps, a 25 mm rear axle and bars 12 mm taller. This platform ran 2013-2015.",{'intake_valve_mm':32.5,'throttle_body_mm':44,'gearbox':'6-speed'},'OEM',s)
R('power_feel','2013-2015 dyno and weight',C,G,"On a magazine dyno the 2013 250 SX-F made 42.89 hp at 13,500 rpm, about 5 hp more than the 2012 at peak and up to 7 more on top, with over 40 hp from 11,000 to 14,000 rpm; the 2015 was quoted at the same peak. It has less torque than the old engine below 7,000 rpm and more above 8,100. It weighed 231 lb in 2013. A fast rider's engine: lazy off idle, strong only when kept high in the revs.",{'peak_hp':42.89,'peak_rpm':13500,'weight_lb_2013':231},'MEASURED',s,'high')
R('setups','2013-2014 tester settings',C,[2013,2014],"A magazine test crew's 2013 250 SX-F setup: fork 0.46 kg/mm springs, 380 cc oil (stock 390; lower again in 5-10 cc steps for mid-stroke harshness), compression 11 clicks out (stock 12), rebound 10 out (stock 12), legs 5 mm up. Shock 5.4 kg/mm spring, 102 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out (stock 16), rebound 13 out (stock 15).",{'fork':'380 cc (stock 390), comp 11 out, reb 10 out, 5 mm up','shock':'5.4 kg/mm, sag 102 mm, HSC 1-3/4 turns, LSC 15 out, reb 13 out'},'TUNER',s,'medium','Tested on the 2013; the 2014 uses the same fork and shock hardware.')
R('setups','2013-2016 gearing',C,[2013,2014,2015,2016],"Stock gearing on the 2013-2016 250 SX-F is 13/50. Most riders add a tooth (13/51), or two for tight tracks; fast riders on big tracks sometimes go the other way to 13/49.",{'stock':'13/50','options':'13/51 (most), 13/52 tight tracks, 13/49 fast riders'},'TUNER',s)
R('ecu_electronics','2013-2015 map switch',C,G,"The 2013-2015 250 SX-F needs KTM's accessory map dial (about $50-60) to change ignition maps: position 1 is softer (retarded, for hardpack), position 2 is about 1 degree advanced and was the testers' choice. Positions 3-10 can be written with KTM's mapping tool; unplugging the dial returns the stock map.",{'map_1':'soft','map_2':'advanced (testers\' pick)'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2015 KTM 250SXF test","https://motocrossactionmag.com/2015-test-ride-ktm-250sxf","2014")
R('identity','2015 changes',C,[2015],"2015 250 SX-F changes: WP 4CS fork (compression in the left leg, rebound in the right), front axle offset reduced from 35 to 33 mm, a forged frame cross tube, a new linkage with a pull rod 2.5 mm longer and a seat 8 mm lower, a revised clutch basket and springs, an orange frame, black Excel rims and Dunlop MX52 tyres.",{'fork':'WP 4CS'},'OEM',s2)
R('setups','2015 tester settings (4CS)',C,[2015],"A magazine test crew's 2015 250 SX-F setup: fork 0.46 kg/mm springs, compression 8 clicks out (stock 15), rebound 13 out (stock 15), legs 5 mm up, oil lowered in small steps against harshness. Shock: testers moved up from the stock 5.4 kg/mm spring to 5.6-5.7, 104 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 19 clicks out (stock 15), rebound 13 out (stock 15). The shock is very sensitive to sag; balance the two ends before touching clickers.",{'fork':'comp 8 out (stock 15), reb 13 out (stock 15), 5 mm up','shock':'5.6-5.7 kg/mm (stock 5.4), sag 104 mm, HSC 1-3/4 turns, LSC 19 out, reb 13 out'},'TUNER',s2)
R('known_issues','2013-2015 weak points and fixes',C,G,"Tester findings on the 2013-2015 250 SX-F: weight (231 lb), the airbox backfire screen restricting flow (an aftermarket cage kit, or remove the screen for closed-course use), a quick-disconnect fuel line that popped off on one test bike (check it before riding and clean the inline filters), low bar mounts, shock G-outs with the stock spring, and the plastic preload ring.",{},'TUNER',s2)

s=F.src(M,"Motocross Action - 2016 KTM 250SXF race test","https://motocrossactionmag.com/2016-mxa-race-test-ktm-250sxf","2015")
G=[2016,2017,2018]
R('identity','2016 redesign',C,G,"The 2016 250 SX-F was all new with a new engine and about 8 lb lighter at 221 lb without fuel: a frame with more torsional and less longitudinal stiffness, softer 4CS fork and shock settings, new radiators, a longer chain guide, lighter discs and Dunlop MX32 tyres. This platform ran 2016-2018.",{'weight_lb':221},'OEM',s)
R('power_feel','2016-2018 dyno and weight',C,G,"On a magazine dyno the 2016 250 SX-F made 43.79 hp at 14,000 rpm and 20.20 lb-ft; the mechanically unchanged 2017 and 2018 were quoted at the same figure. Weight was 221 lb in 2016 and 218 lb from 2017 with the air fork, about 10 lb lighter than the 2018 CRF250R. A total-commitment powerband: soft off the bottom, it comes alive near the 14,000 rpm limit.",{'peak_hp':43.79,'peak_rpm':14000,'peak_torque_lbft':20.2,'weight_lb_2016':221,'weight_lb_2017_18':218},'MEASURED',s,'high')
R('setups','2016 tester settings (4CS)',C,[2016],"A magazine test crew's 2016 250 SX-F setup: fork 4.6 N/mm springs, compression 6 clicks out (stock 15), rebound 10 out (stock 15), legs 3 mm up. Shock 45 N/mm spring, 105 mm sag, high-speed compression 1-1/2 turns out (stock 2), low-speed 8 clicks out (stock 15), rebound 6 out (stock 15).",{'fork':'4.6 N/mm, comp 6 out (stock 15), reb 10 out (stock 15), 3 mm up','shock':'45 N/mm, sag 105 mm, HSC 1-1/2 turns, LSC 8 out, reb 6 out'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 KTM 250SXF race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-250sxf","2016")
R('identity','2017 changes',C,[2017],"2017 250 SX-F changes: WP AER 48 air fork (3.6 lb lighter than the 4CS), a 42 N/mm shock spring (was 45), the handlebar multi-switch with two maps, traction control and launch control, a longer rear brake pedal with milder pads, lighter head stays, a stiffer top clamp, an hour meter and gearing changed from 13/50 to 14/51. The engine is mechanically unchanged.",{'fork':'WP AER 48 (air)','shock_spring':'42 N/mm','gearing':'14/51'},'OEM',s2)
R('setups','2017-2018 tester settings (AER)',C,[2017,2018],"A magazine test crew's 2017-2018 250 SX-F setup: fork air 140 psi on the 2017 (stock 154); on the 2018, 130 psi for novices, 140 for vets, 150 for intermediates and 154 for pros (stock 156); compression 20 clicks out, rebound 15 out, legs at the third line. Shock stock 42 N/mm spring, 105 mm sag (stock 110), high-speed compression 2 turns out, low-speed 15 clicks out, rebound 10 out (stock 15).",{'fork_psi':'130 novice / 140 vet / 150 intermediate / 154 pro','fork':'comp 20 out, reb 15 out, third line','shock':'42 N/mm, sag 105 mm, HSC 2 turns, LSC 15 out, reb 10 out (stock 15)'},'TUNER',s2)
R('setups','2017-2019 gearing',C,[2017,2018,2019],"Stock gearing on the 2017-2019 250 SX-F is 14/51 (3.64), which most riders find tall. The cheap fix is a 13-tooth countershaft sprocket; the factory race team ran 14/53 (3.78), and stronger riders on fast tracks used 14/50.",{'stock':'14/51','options':'13/51 for novices and vets; 14/53 race team; 14/50 fast tracks'},'TUNER',s2)
R('ecu_electronics','2016-2018 maps',C,G,"On the 2016-2018 250 SX-F map 1 is the mild map (weak from bottom to mid) and map 2 the aggressive one, which was the only map testers used. Traction control takes away bottom and mid on a 250 and was left off; launch control is worth using on concrete and muddy starts. On the 2016 the map dial is under the seat and the bar switch selects it; from 2017 it is all on the left-bar multi-switch.",{'map_1':'mild','map_2':'aggressive (testers\' pick)'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2018 KTM 250SXF race test","https://motocrossactionmag.com/mxa-race-test-2018-ktm-250sxf","2017")
R('identity','2018 changes',C,[2018],"2018 250 SX-F changes: AER fork with a new air seal, air piston and valving, shock settings to match, a stronger battery at the same weight, nitrided clutch steels, a C4 gearbox bearing, a new shift star, radiator guards that shed mud and an orange frame. List price $8,699.",{'msrp_usd':8699},'OEM',s3)
R('known_issues','2016-2018 weak points and fixes',C,G,"Tester findings on the 2016-2018 250 SX-F: spokes loosen (watch the one by the rear rim lock) and sprocket bolts need thread-locker, neutral is hard to find in the pits, the gas cap sticks, the exhaust needs the shock out to remove (fixed for 2019), the plastic shock collar is fragile (lever it round with a long screwdriver while turning the spring by hand), the brake pedal spring pops off unless its tang faces inward, and the stock front tyre sheds side knobs on hardpack. The front-end grip and cornering were rated the best in the class.",{},'TUNER',s3)

s=F.src(M,"Motocross Action - 2019 KTM 250SXF race test","https://motocrossactionmag.com/mxa-race-test-2019-ktm-250sxf","2018")
R('identity','2019 changes',C,[2019],"2019 250 SX-F changes: a frame 10% stiffer in torsion and 2% stiffer lengthwise (painted black), a subframe 40 mm longer, a Belleville-spring clutch, a lithium battery, a new airbox, a three-piece exhaust, radiators 12 mm lower with 11% more coolant, revised valve timing and mapping on the same gear ratios, a swingarm slot that lets the wheel sit 5 mm further back, a fork with half the negative-chamber volume and a recommended pressure cut from 154 to 149 psi, and a top clamp 5% stiffer. Tank 1.85 gal; weight 218 lb.",{'weight_lb':218,'tank_gal':1.85,'fork_psi_recommended':149},'OEM',s)
R('setups','2019 tester settings (AER)',C,[2019],"A magazine test crew's 2019 250 SX-F setup: fork air 136 psi (stock 149; lighter riders 132 or less), compression 28 clicks out (stock 15), rebound 17 out (stock 15), legs at the third line. Shock stock 42 N/mm spring (45 over 185 lb), 107 mm sag (stock 105; it cured a front-end oversteer in sand), high-speed compression 2-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 11 out (stock 15).",{'fork_psi':'136 (stock 149)','fork':'comp 28 out (stock 15), reb 17 out (stock 15), third line','shock':'42 N/mm, sag 107 mm, HSC 2-3/4 turns (stock 2), LSC 15 out, reb 11 out'},'TUNER',s)
R('engine_mods','2019 airbox cover and maps',C,[2019],"The 2019 250 SX-F is flat off the bottom with the stock airbox cover. Drilling ten 1-1/4 in holes in the cover gave the best result in testing; trimming the inner lip helped a little. On this year map 1 (standard) had the better bottom and mid and map 2 was top-heavy; with the cover opened, map 1 can pop lean on deceleration.",{},'TUNER',s)

if __name__=='__main__': F.write()
